import { useEffect, useState } from "react";
import { ActivityIndicator, Alert, RefreshControl, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, View } from "react-native";
import { router } from "expo-router";
import MaterialIcons from "@expo/vector-icons/MaterialIcons";
import { ScreenContainer } from "@/components/screen-container";
import { djangoApi } from "@/lib/django-api";

type Payout={id:number;amount:string;currency:string;status:string;reference:string;created_at:string};
type Finance={vendor:number;vendor_name:string;currency:string;earned:string;paid:string;pending:string;available:string;payouts:Payout[]};
export default function VendorWalletScreen(){const [finance,setFinance]=useState<Finance|null>(null);const [amount,setAmount]=useState("");const [loading,setLoading]=useState(true);const [refreshing,setRefreshing]=useState(false);const [sending,setSending]=useState(false);
 async function load(){try{const data=await djangoApi<Finance>("/api/vendor-finance/summary/");setFinance(data)}catch{setFinance(null)}finally{setLoading(false);setRefreshing(false)}}useEffect(()=>{load()},[]);
 async function requestPayout(){if(!amount||Number(amount)<=0)return Alert.alert("مبلغ غير صالح","أدخل قيمة موجبة.");if(finance&&Number(amount)>Number(finance.available))return Alert.alert("الرصيد غير كافٍ",`المتاح للسحب ${finance.available} ${finance.currency}.`);setSending(true);try{await djangoApi("/api/vendor-finance/request_payout/",{method:"POST",body:JSON.stringify({amount})});setAmount("");Alert.alert("تم الطلب","أُرسل طلب السحب إلى الإدارة للمراجعة.");await load()}catch(error){Alert.alert("تعذر طلب السحب",error instanceof Error?error.message:"حدث خطأ")}finally{setSending(false)}}
 if(loading)return <ScreenContainer><View style={styles.center}><ActivityIndicator color="#E60023"/><Text style={styles.muted}>جارٍ تحميل المستحقات...</Text></View></ScreenContainer>;
 return <ScreenContainer className="bg-[#F6F7F9]" edges={["top","bottom","left","right"]}><View style={styles.header}><TouchableOpacity onPress={()=>router.back()}><MaterialIcons name="arrow-forward" size={23} color="#111"/></TouchableOpacity><Text style={styles.title}>مستحقات التاجر</Text><View style={{width:23}}/></View><ScrollView contentContainerStyle={styles.page} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={()=>{setRefreshing(true);load()}}/>}><View style={styles.balance}><View style={styles.balanceTop}><MaterialIcons name="account-balance-wallet" size={19} color="#FFF"/><Text style={styles.balanceLabel}>المتاح للسحب</Text></View><Text style={styles.balanceValue}>{finance?.available||"0.00"} <Text style={styles.currency}>{finance?.currency||"YER"}</Text></Text></View><View style={styles.summaryRow}><Stat label="إجمالي المكتسب" value={finance?.earned||"0"}/><Stat label="تم دفعه" value={finance?.paid||"0"}/><Stat label="طلبات معلقة" value={finance?.pending||"0"}/></View><View style={styles.card}><Text style={styles.heading}>طلب سحب</Text><Text style={styles.help}>يجب أن يكون المبلغ ضمن الرصيد المتاح. تتم مراجعة الطلب من الإدارة قبل التحويل.</Text><TextInput value={amount} onChangeText={setAmount} placeholder="المبلغ" keyboardType="decimal-pad" style={styles.input} textAlign="right"/><TouchableOpacity style={styles.button} onPress={requestPayout} disabled={sending}><Text style={styles.buttonText}>{sending?"جارٍ الإرسال...":"طلب سحب الرصيد"}</Text></TouchableOpacity></View><Text style={styles.section}>طلبات السحب السابقة</Text><View style={styles.card}>{finance?.payouts?.length?finance.payouts.map(p=><View key={p.id} style={styles.payout}><View style={styles.payoutCopy}><Text style={styles.reference}>{p.reference}</Text><Text style={styles.date}>{new Date(p.created_at).toLocaleDateString("ar-YE")}</Text></View><View style={styles.payoutAmount}><Text style={styles.amount}>{p.amount} {p.currency}</Text><Text style={[styles.status,{color:statusColor(p.status)}]}>{translate(p.status)}</Text></View></View>):<Text style={styles.muted}>لا توجد طلبات سحب.</Text>}</View></ScrollView></ScreenContainer>}
function Stat({label,value}:{label:string;value:string}){return <View style={styles.stat}><Text style={styles.statValue}>{value}</Text><Text style={styles.statLabel}>{label}</Text></View>}
function translate(s:string){return({pending:"قيد المراجعة",approved:"معتمد",paid:"مدفوع",rejected:"مرفوض"} as Record<string,string>)[s]||s}function statusColor(s:string){return s==="paid"?"#168451":s==="rejected"?"#E60023":"#C77900"}
const styles=StyleSheet.create({header:{height:58,backgroundColor:"#FFF",paddingHorizontal:15,flexDirection:"row",justifyContent:"space-between",alignItems:"center",borderBottomWidth:1,borderColor:"#EEE"},title:{fontSize:17,fontWeight:"900",color:"#111"},page:{padding:12,paddingBottom:150,maxWidth:820,width:"100%",alignSelf:"center"},balance:{backgroundColor:"#111",borderRadius:16,padding:20,marginBottom:10},balanceTop:{flexDirection:"row-reverse",alignItems:"center",gap:8},balanceLabel:{color:"#D1D1D1",fontSize:12,fontWeight:"700"},balanceValue:{color:"#FFF",fontSize:31,fontWeight:"900",textAlign:"right",marginTop:12},currency:{fontSize:14,color:"#AAA"},summaryRow:{flexDirection:"row-reverse",gap:8,marginBottom:10},stat:{flex:1,minWidth:0,backgroundColor:"#FFF",borderRadius:12,padding:12,borderWidth:1,borderColor:"#EEE"},statValue:{fontSize:16,fontWeight:"900",color:"#111",textAlign:"right"},statLabel:{fontSize:10,color:"#777",textAlign:"right",marginTop:3},card:{backgroundColor:"#FFF",borderRadius:14,padding:14,marginBottom:12,borderWidth:1,borderColor:"#EEE"},heading:{fontSize:16,fontWeight:"900",textAlign:"right",marginBottom:8},help:{fontSize:10,color:"#777",lineHeight:16,textAlign:"right",marginBottom:10},input:{backgroundColor:"#F7F7F8",borderWidth:1,borderColor:"#E2E2E2",borderRadius:10,paddingHorizontal:12,paddingVertical:11,fontSize:13,marginBottom:9},button:{backgroundColor:"#E60023",paddingVertical:13,borderRadius:10,alignItems:"center"},buttonText:{color:"#FFF",fontWeight:"900",fontSize:13},section:{fontSize:16,fontWeight:"900",textAlign:"right",marginHorizontal:2,marginBottom:8},payout:{flexDirection:"row-reverse",justifyContent:"space-between",alignItems:"center",paddingVertical:12,borderBottomWidth:1,borderColor:"#F1F1F1"},payoutCopy:{alignItems:"flex-end",flex:1},payoutAmount:{alignItems:"flex-start",marginLeft:10},reference:{fontSize:11,fontWeight:"800",color:"#333",textAlign:"right"},date:{fontSize:9,color:"#999",marginTop:3},amount:{fontSize:13,fontWeight:"900",color:"#111"},status:{fontSize:10,fontWeight:"800",marginTop:3},muted:{fontSize:12,color:"#888",textAlign:"center"},center:{flex:1,alignItems:"center",justifyContent:"center",gap:9}});
